import { test, expect } from '@playwright/test';

test.describe('Login Form Validation - Empty Fields', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should prevent form submission with empty username and password fields', async ({ page }) => {
    // Set up intercept for login API
    await page.route('**/api/auth/login', (route) => {
      route.abort('API call aborted');
    });

    // Locate and fill username field
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('testuser');

    // Locate and clear password field
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('');

    // Locate and clear email field
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('');

    // Locate and clear submit button
    const submitButton = page.getByRole('button', { name: /sign in/i });
    await submitButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText('Username and password are required');
    await expect(errorMessage).toBeVisible();

    // Verify form is not submitted
    const form = page.locator('[data-testid="login-form"]');
    await expect(form).toBeVisible();

    // Verify form has not been reset
    const usernameInputValue = await usernameInput.evaluate((el) => el.value);
    expect(usernameInputValue).toBe('testuser');

    const passwordInputValue = await passwordInput.evaluate((el) => el.value);
    expect(passwordInputValue).toBe('');

    // Verify error message is visible
    await expect(errorMessage).toBeVisible();
  });

  test('should allow form submission with valid username and password', async ({ page }) => {
    // Set up intercept for login API
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Locate and fill username field
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('validuser');

    // Locate and fill password field
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('validpassword');

    // Locate and clear email field
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('');

    // Locate and click submit button
    const submitButton = page.getByRole('button', { name: /sign in/i });
    await submitButton.click();

    // Verify success message is displayed
    const successMessage = page.getByText('Login successful');
    await expect(successMessage).toBeVisible();

    // Verify form is reset
    const usernameInputValue = await usernameInput.evaluate((el) => el.value);
    expect(usernameInputValue).toBe('');

    const passwordInputValue = await passwordInput.evaluate((el) => el.value);
    expect(passwordInputValue).toBe('');

    // Verify form is not visible
    const form = page.locator('[data-testid="login-form"]');
    await expect(form).not.toBeVisible();
  });
});
